  if (sessionLoaded && accountBlocked) return <main className="access-gate"><section><span className="brand-mark">A<span>+</span></span><h1>Acceso desactivado</h1><p>La persona administradora ha retirado temporalmente el permiso de esta cuenta.</p><a className="signin-button" href="/signout-with-chatgpt?return_to=/">Salir de esta cuenta</a></section></main>;
